-- VoltHub v1.2 — product database.
-- Optional: php/db.php creates this database and these tables by itself the first time the site opens.
-- Import this file in phpMyAdmin only if you prefer to set it up by hand (it also loads the 10 sample products).

CREATE DATABASE IF NOT EXISTS `volthub` DEFAULT CHARACTER SET utf8mb4;
USE `volthub`;

-- Products: one row per item sold in the store (storefront + admin inventory read and write this table).
CREATE TABLE IF NOT EXISTS `products` (
  `id`          VARCHAR(20)   NOT NULL,                       -- p1, p2 ... (new products: p + random hex)
  `pos`         INT           NOT NULL DEFAULT 0,             -- display order, lowest first
  `name`        VARCHAR(150)  NOT NULL,
  `category`    VARCHAR(60)   NOT NULL,
  `price`       DECIMAL(10,2) NOT NULL DEFAULT 0,
  `stock`       INT           NOT NULL DEFAULT 0,
  `description` TEXT          NOT NULL,
  `img`         MEDIUMTEXT    NOT NULL,                       -- image URL or inline SVG data URI
  `created_at`  TIMESTAMP     NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`  TIMESTAMP     NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_category` (`category`),
  KEY `idx_pos` (`pos`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Product photos (for the admin photo-upload feature). Deleted automatically with their product.
CREATE TABLE IF NOT EXISTS `product_photos` (
  `id`          INT          NOT NULL AUTO_INCREMENT,
  `product_id`  VARCHAR(20)  NOT NULL,
  `file_name`   VARCHAR(255) NOT NULL,
  `file_path`   VARCHAR(255) NOT NULL,                        -- e.g. uploads/photo.png
  `uploaded_at` TIMESTAMP    NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `product_id` (`product_id`),
  CONSTRAINT `fk_photo_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

